def f(x):
    return x**4 - 8*x**3

def check_point(x, y, z, w):
    if abs(x+y+z+w - 12) > 1e-6 or abs(x**2+y**2+z**2+w**2 - 48) > 1e-6:
        return None
    return f(x) + f(y) + f(z) + f(w)

print(f"f(4, 4, 4, 0) = {check_point(4, 4, 4, 0)}")
import math
sqrt3 = math.sqrt(3)
print(f"f(3+sqrt3, 3+sqrt3, 3-sqrt3, 3-sqrt3) = {check_point(3+sqrt3, 3+sqrt3, 3-sqrt3, 3-sqrt3)}")
print(f"f(2, 2, 2, 6) = {check_point(2, 2, 2, 6)}")
